# HA Paper display config
version: 1
apps:
  - id: home
    title: Home
  - id: house
    title: House
screens:
  - id: overview
    app: home
    title: Home
    widgets:
      - {type: clock, cs: 2}
      - {type: stat, entity: sensor.lounge_temperature, label: Inside}
      - {type: stat, entity: sensor.p1_meter_power, label: Home use}
      - {type: stat, entity: sensor.garden_station_outside_temperature, label: Outside}
  - id: energy
    app: home
    title: Energy
    widgets:
      - {type: stat, entity: sensor.p1_meter_power, label: Home use}
      - {type: bars, series: usage, cs: 4}
  - id: lights
    app: house
    title: Lights
    widgets:
      - {type: lightList, areas: lounge kitchen bedroom, cs: 4, rs: 2}
  - id: climate
    app: house
    title: Heating
    widgets:
      - {type: zoneList, cs: 4, rs: 2}
  - id: rooms
    app: house
    title: Rooms
    widgets:
      - {type: stat, entity: sensor.lounge_temperature, label: Lounge}
      - {type: stat, entity: sensor.kitchen_thermometer_temperature, label: Kitchen}
      - {type: stat, entity: sensor.bedroom_temperature, label: Bedroom}
      - {type: stat, entity: sensor.office_temperature, label: Office upstairs}

