    app: home
    title: Home
    widgets:
      - {type: clock, cs: 2}
      - {type: price}
      - {type: stat, entity: sensor.co2_living_room_temperature, label: Inside}
      - {type: stat, entity: sensor.envoy_482100000000_current_power_production, label: Solar}
      - {type: stat, entity: sensor.envoy_482100000000_current_power_consumption, label: Home use}
      - {type: stat, entity: sensor.electricity_meter_power_consumption, label: Grid}
      - {type: stat, entity: sensor.shelly_ht_outdoor_temperature, label: Outside}
  - id: prices
    app: home
    title: Energy prices
    widgets:
      - {type: price}
      - {type: bars, series: prices, cs: 4}
  - id: energy
    app: home
    title: Energy
    widgets:
      - {type: stat, entity: sensor.home_energy_usage_today, label: Used today}
      - {type: stat, entity: sensor.envoy_482100000000_current_power_consumption, label: Home use}
      - {type: bars, series: usage, cs: 4}
  - id: solar
    app: home
    title: Solar
    widgets:
      - {type: stat, entity: sensor.envoy_482100000000_current_power_production, label: Solar}
      - {type: stat, entity: sensor.envoy_482100000000_energy_production_today, label: Solar today}
      - {type: bars, series: solar, cs: 4}
  - id: lights
    app: house
    title: Lights
    widgets:
      - {type: lightList, entities: light.living_room light.kitchen light.hallway light.toilet light.bedroom light.desk_lamp_playroom light.playroom light.guest_room_lamp light.bathroom_mirror light.office_desk light.attic_tube_light light.garage_lamp light.outdoor light.driveway_spot, cs: 4, rs: 2}
  - id: climate
    app: house
    title: Heating
    widgets:
      - {type: zoneList, entities: climate.attic climate.bathroom climate.bedroom climate.kitchen climate.living_room climate.playroom, cs: 4, rs: 2}
  - id: rooms
    app: house
    title: Rooms
    widgets:
      - {type: stat, entity: sensor.co2_living_room_temperature, label: Living room}
      - {type: stat, entity: sensor.kitchen_temperature, label: Kitchen}
      - {type: stat, entity: sensor.hallway_temperature, label: Hallway}
      - {type: stat, entity: sensor.thermometer_toilet_temperature, label: Toilet}
      - {type: stat, entity: sensor.bedroom_temperature, label: Bedroom}
      - {type: stat, entity: sensor.playroom_temperature, label: Playroom & Study}
      - {type: stat, entity: sensor.thermometer_guest_room_temperature, label: Guest room}
      - {type: stat, entity: sensor.bathroom_temperature, label: Bathroom}

# HA Paper display config
version: 1
screens:
  - id: overview
    app: home
    title: Home
    widgets:
      - {type: clock, cs: 2}
      - {type: price}
      - {type: stat, entity: sensor.t9, label: Inside}
      - {type: stat, entity: sensor.roof_output, label: Solar}
      - {type: stat, entity: sensor.powerwall_load_power, label: Home use}
      - {type: gauge, entity: sensor.powerwall_battery_charge, label: Home battery}
      - {type: stat, entity: sensor.site_grid_power, label: Grid}
  - id: prices
    app: home
    title: Energy prices
    widgets:
      - {type: price}
      - {type: bars, series: prices, cs: 4}
  - id: energy
    app: home
    title: Energy
    widgets:
      - {type: stat, entity: sensor.powerwall_load_power, label: Home use}
      - {type: bars, series: usage, cs: 4}
  - id: solar
    app: home
    title: Solar & battery
    widgets:
      - {type: stat, entity: sensor.roof_output, label: Solar}
      - {type: gauge, entity: sensor.powerwall_battery_charge, label: Home battery}
      - {type: stat, entity: sensor.powerwall_battery_power, label: Battery}
      - {type: bars, series: solar, cs: 4}
  - id: lights
    app: house
    title: Lights
    widgets:
      - {type: lightList, cs: 4, rs: 2}
  - id: rooms
    app: house
    title: Rooms
    widgets:
      - {type: stat, entity: sensor.t10, label: Hall}
      - {type: stat, entity: sensor.t9, label: Living room}
      - {type: stat, entity: sensor.t8, label: Kids 1}
      - {type: stat, entity: sensor.t7, label: Bath}
      - {type: stat, entity: sensor.t6, label: Study}
      - {type: stat, entity: sensor.t5, label: Attic}
      - {type: stat, entity: sensor.t4, label: Cellar}
      - {type: stat, entity: sensor.t3, label: Guest}
  - id: travel
    app: travel
    title: Travel
    widgets:
      - {type: route, entity: sensor.x4_route_car, cs: 2}
      - {type: route, entity: sensor.x4_route_drive, mode: car, cs: 2}
      - {type: route, entity: sensor.x4_route_school, cs: 2}
      - {type: route, entity: sensor.x4_route_work, cs: 2}
